<meta name="viewport" content="width=device-width, initial-scale=1">
<title>HANGAR 20 — Drone Bay</title>
<style>
  :root { --cyan:#4fd8ff; --dim:#33455a; --txt:#9fb6c6; }
  * { margin:0; padding:0; box-sizing:border-box; }
