    font:inherit; font-size:11px; letter-spacing:.18em; padding:9px 14px; cursor:pointer;
    text-transform:uppercase; transition:all .18s ease; backdrop-filter:blur(4px);
  }
  #controls button:hover { border-color:var(--cyan); color:var(--cyan); }
  #controls button.active { border-color:var(--cyan); color:var(--cyan); box-shadow:0 0 16px rgba(79,216,255,.3), inset 0 0 10px rgba(79,216,255,.12); }
  #hint { position:fixed; bottom:22px; right:22px; z-index:10; font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:10px; letter-spacing:.2em; color:var(--dim); text-align:right; line-height:2; user-select:none; pointer-events:none; }
  #hint b { color:#5f7f97; }
  #vignette { position:fixed; inset:0; pointer-events:none; z-index:5; background:radial-gradient(ellipse at center, transparent 52%, rgba(2,4,8,.6) 100%); }
  #scan { position:fixed; inset:0; pointer-events:none; z-index:6; opacity:.5; background:repeating-linear-gradient(0deg, rgba(255,255,255,.016) 0 1px, transparent 1px 3px); }
  #err { position:fixed; inset:0; z-index:50; display:flex; align-items:center; justify-content:center; background:rgba(3,5,9,.92); color:#ff7a7a; font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:13px; letter-spacing:.12em; text-align:center; line-height:2; padding:40px; }
