  <h1>HANGAR&nbsp;20</h1>
  <div class="sub">DRONE BAY · SECTOR 7G</div>
  <div id="status">
    FORMATION&nbsp;<b id="s-form">GRID</b><br>
    CAMERA&nbsp;&nbsp;&nbsp;&nbsp;<b id="s-cam">MANUAL</b><br>
    UAV&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b id="s-uav">8</b> / 8
  </div>
