<div id="controls">
  <button id="b-form" class="active">[F] Formation</button>
  <button id="b-cam">[C] Cinematic Cam</button>
  <button id="b-reset">[R] Reset Cam</button>
</div>
<div id="hint"><b>DRAG</b> ORBIT &nbsp;·&nbsp; <b>SCROLL</b> ZOOM<br><b>F</b> FORMATION &nbsp;·&nbsp; <b>C</b> CINEMATIC &nbsp;·&nbsp; <b>R</b> RESET</div>
<div id="err" hidden></div>

<script type="module">
/* ================================================================
   HANGAR 20 — single-file Three.js sci-fi drone bay
   three.js is the only external dependency (CDN, 3 fallbacks).
   All geometry, textures and logic below are procedural/inline.
   ================================================================ */
const $ = (id) => document.getElementById(id);

async function loadThree() {
  const urls = [
    'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js',
    'https://unpkg.com/three@0.160.0/build/three.module.js',
    'https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.js',
  ];
  for (const u of urls) {
    try { return await import(u); } catch (e) { /* try next */ }
  }
  throw new Error('three.js CDN unreachable');
}

function fatal(html) {
  const el = $('err');
  el.hidden = false;
  el.innerHTML = html;
}

let THREE = null;
try {
  THREE = await loadThree();
  start(THREE);
} catch (e) {
  fatal('<b>HANGAR OFFLINE</b><br>Could not initialise the scene: ' + e.message +
        '<br><br>Check your network connection (three.js is fetched from a CDN) and reload.');
  console.error(e);
}

function start(THREE) {
  /* ---------------- renderer / scene ---------------- */
  const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.12;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  document.body.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x04060a);
  scene.fog = new THREE.FogExp2(0x070b13, 0.011);

  const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 400);

  /* ---------------- procedural textures ---------------- */
  function makeCanvas(w, h, draw) {
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const g = c.getContext('2d');
    draw(g, w, h);
    const t = new THREE.CanvasTexture(c);
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
    return t;
  }

  const glowTex = makeCanvas(256, 256, (g) => {
    const r = g.createRadialGradient(128, 128, 0, 128, 128, 128);
    r.addColorStop(0, 'rgba(255,255,255,1)');
    r.addColorStop(0.22, 'rgba(255,255,255,0.55)');
    r.addColorStop(0.55, 'rgba(255,255,255,0.12)');
    r.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = r; g.fillRect(0, 0, 256, 256);
  });

  const fogTex = makeCanvas(256, 256, (g) => {
    g.clearRect(0, 0, 256, 256);
    const blob = (x, y, r, a) => {
      const gr = g.createRadialGradient(x, y, 0, x, y, r);
      gr.addColorStop(0, 'rgba(255,255,255,' + a + ')');
      gr.addColorStop(1, 'rgba(255,255,255,0)');
      g.fillStyle = gr; g.fillRect(0, 0, 256, 256);
    };
    blob(128, 128, 120, 0.5); blob(70, 90, 70, 0.4); blob(180, 160, 80, 0.35); blob(150, 60, 50, 0.3);
  });

  const shaftTex = makeCanvas(256, 512, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    let gr = g.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, 'rgba(255,255,255,0)');
    gr.addColorStop(0.55, 'rgba(255,255,255,0.25)');
    gr.addColorStop(1, 'rgba(255,255,255,0.85)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
    g.globalCompositeOperation = 'destination-in';
    gr = g.createLinearGradient(0, 0, w, 0);
    gr.addColorStop(0, 'rgba(255,255,255,0)');
    gr.addColorStop(0.5, 'rgba(255,255,255,1)');
    gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
    g.globalCompositeOperation = 'source-over';
  });

  const beamTex = makeCanvas(256, 64, (g, w, h) => {
    const gr = g.createLinearGradient(0, 0, w, 0);
    gr.addColorStop(0, 'rgba(255,255,255,0.9)');
    gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
  });

  const floorTex = makeCanvas(1024, 2048, (g, w, h) => {
    g.fillStyle = '#0c0f14'; g.fillRect(0, 0, w, h);
    let gr = g.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, 'rgba(30,40,52,0.20)');
    gr.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
    g.lineWidth = 1;
    for (let x = 0; x <= w; x += 73) {
      g.strokeStyle = 'rgba(90,130,160,' + (x % 146 === 0 ? 0.10 : 0.045) + ')';
      g.beginPath(); g.moveTo(x, 0); g.lineTo(x, h); g.stroke();
    }
    for (let y = 0; y <= h; y += 73) {
      g.strokeStyle = 'rgba(90,130,160,' + (y % 146 === 0 ? 0.10 : 0.045) + ')';
      g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke();
    }
    for (let i = 0; i < 300; i++) {
      const x = Math.random() * w, y = Math.random() * h;
      const l = 15 + Math.random() * 90, a = Math.random() * Math.PI;
      g.strokeStyle = 'rgba(140,160,180,' + (0.015 + Math.random() * 0.04).toFixed(3) + ')';
      g.lineWidth = 0.5 + Math.random() * 1.5;
      g.beginPath(); g.moveTo(x, y);
      g.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); g.stroke();
    }
    // worn landing pad (pad sits at u .5, v .667 -> canvas y ~ .333)
    const px = w * 0.5, py = h * 0.333;
    const pg = g.createRadialGradient(px, py, 20, px, py, 300);
    pg.addColorStop(0, 'rgba(50,70,90,0.16)');
    pg.addColorStop(0.7, 'rgba(40,55,70,0.08)');
    pg.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = pg; g.fillRect(0, 0, w, h);
    // faint painted guide lanes from door (canvas bottom) toward pad
    g.strokeStyle = 'rgba(70,180,220,0.07)';
    g.lineWidth = 6;
    g.beginPath(); g.moveTo(w * 0.375, h); g.lineTo(w * 0.375, py); g.stroke();
    g.beginPath(); g.moveTo(w * 0.625, h); g.lineTo(w * 0.625, py); g.stroke();
  });

  const skyTex = makeCanvas(1024, 512, (g, w, h) => {
    let gr = g.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, '#020308');
    gr.addColorStop(0.55, '#081020');
    gr.addColorStop(0.8, '#14263a');
    gr.addColorStop(1, '#2a4258');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 420; i++) {
      const x = Math.random() * w, y = Math.random() * h * 0.75, r = 0.4 + Math.random() * 1.3;
      g.fillStyle = 'rgba(255,255,255,' + (0.2 + Math.random() * 0.7).toFixed(2) + ')';
      g.fillRect(x, y, r, r);
    }
    const px = w * 0.68, py = h * 0.30, pr = 52;
    const pg = g.createRadialGradient(px - pr * 0.3, py - pr * 0.3, pr * 0.2, px, py, pr);
    pg.addColorStop(0, 'rgba(140,190,235,0.9)');
    pg.addColorStop(0.7, 'rgba(70,110,160,0.7)');
    pg.addColorStop(1, 'rgba(30,50,80,0)');
    g.fillStyle = pg; g.beginPath(); g.arc(px, py, pr, 0, 7); g.fill();
    const hg = g.createRadialGradient(w * 0.5, h * 1.02, h * 0.1, w * 0.5, h * 1.02, h * 0.55);
    hg.addColorStop(0, 'rgba(255,170,90,0.5)');
    hg.addColorStop(0.5, 'rgba(180,90,40,0.18)');
    hg.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = hg; g.fillRect(0, 0, w, h);
  });

  const hazardTex = makeCanvas(256, 128, (g, w, h) => {
    g.fillStyle = '#101216'; g.fillRect(0, 0, w, h);
    g.save(); g.translate(w / 2, h / 2); g.rotate(-Math.PI / 4); g.translate(-w, -h);
    g.fillStyle = 'rgba(255,170,60,0.5)';
    for (let x = -h; x < w * 1.5; x += 64) g.fillRect(x, 0, 32, h * 2);
    g.restore();
  });

  const signTex = makeCanvas(1024, 256, (g) => {
    g.clearRect(0, 0, 1024, 256);
    g.shadowColor = 'rgba(80,220,255,0.9)'; g.shadowBlur = 24;
    g.fillStyle = '#6fe3ff';
    g.font = '700 110px ui-monospace, SFMono-Regular, Menlo, monospace';
    g.fillText('HANGAR 20', 40, 130);
    g.shadowBlur = 10;
    g.font = '400 32px ui-monospace, SFMono-Regular, Menlo, monospace';
    g.fillStyle = 'rgba(160,210,235,0.85)';
    g.fillText('DRONE BAY 07 // UNMANNED ZONE — AUTHORIZED CREW ONLY', 42, 196);
  });

  /* ---------------- materials ---------------- */
  const matFloor = new THREE.MeshStandardMaterial({ map: floorTex, roughness: 0.5, metalness: 0.45 });
  const matWall  = new THREE.MeshStandardMaterial({ color: 0x11161d, roughness: 0.85, metalness: 0.25 });
  const matWall2 = new THREE.MeshStandardMaterial({ color: 0x0e1218, roughness: 0.9,  metalness: 0.2 });
  const matCeil  = new THREE.MeshStandardMaterial({ color: 0x0a0d12, roughness: 0.95, metalness: 0.15 });
  const matTruss = new THREE.MeshStandardMaterial({ color: 0x1b232e, roughness: 0.55, metalness: 0.75 });
  const matDark  = new THREE.MeshStandardMaterial({ color: 0x141a22, roughness: 0.5,  metalness: 0.6 });
  const matDrone = new THREE.MeshStandardMaterial({ color: 0x2a333f, roughness: 0.35, metalness: 0.8 });
  const matDroneDark = new THREE.MeshStandardMaterial({ color: 0x161c24, roughness: 0.45, metalness: 0.7 });
  const matSlat  = new THREE.MeshStandardMaterial({ color: 0x232c38, roughness: 0.5,  metalness: 0.7 });

  /* ---------------- room ---------------- */
  const W = 56, H = 16, D = 120, HW = 28, HD = 60;
  const openW = 36, openH = 13;
  const room = new THREE.Group(); scene.add(room);

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(W, D), matFloor);
  floor.rotation.x = -Math.PI / 2; room.add(floor);

  const ceil = new THREE.Mesh(new THREE.PlaneGeometry(W, D), matCeil);
  ceil.rotation.x = Math.PI / 2; ceil.position.y = H; room.add(ceil);

  const wallL = new THREE.Mesh(new THREE.PlaneGeometry(D, H), matWall);
  wallL.rotation.y = Math.PI / 2; wallL.position.set(-HW, H / 2, 0); room.add(wallL);
  const wallR = new THREE.Mesh(new THREE.PlaneGeometry(D, H), matWall);
  wallR.rotation.y = -Math.PI / 2; wallR.position.set(HW, H / 2, 0); room.add(wallR);
  const wallB = new THREE.Mesh(new THREE.PlaneGeometry(W, H), matWall2);
  wallB.position.set(0, H / 2, -HD); room.add(wallB);

  // front wall (door side) — opening 36 x 13 in the center
  const sideW = (W - openW) / 2;
  const fp1 = new THREE.Mesh(new THREE.BoxGeometry(sideW, openH, 1.2), matWall);
  fp1.position.set(-(openW / 2 + sideW / 2), openH / 2, HD); room.add(fp1);
  const fp2 = new THREE.Mesh(new THREE.BoxGeometry(sideW, openH, 1.2), matWall);
  fp2.position.set(openW / 2 + sideW / 2, openH / 2, HD); room.add(fp2);
  const lintel = new THREE.Mesh(new THREE.BoxGeometry(W, H - openH, 1.2), matWall);
  lintel.position.set(0, openH + (H - openH) / 2, HD); room.add(lintel);

  // emissive door-frame trim
  const trimMat = new THREE.MeshBasicMaterial({ color: 0x1d5a74 });
  const trimH1 = new THREE.Mesh(new THREE.BoxGeometry(openW + 0.8, 0.18, 0.25), trimMat);
  trimH1.position.set(0, 0.09, HD - 0.55); room.add(trimH1);
  const trimH2 = new THREE.Mesh(new THREE.BoxGeometry(openW + 0.8, 0.18, 0.25), trimMat);
  trimH2.position.set(0, openH + 0.09, HD - 0.55); room.add(trimH2);
  const trimV1 = new THREE.Mesh(new THREE.BoxGeometry(0.18, openH, 0.25), trimMat);
  trimV1.position.set(-(openW / 2 + 0.09), openH / 2, HD - 0.55); room.add(trimV1);
  const trimV2 = new THREE.Mesh(new THREE.BoxGeometry(0.18, openH, 0.25), trimMat);
  trimV2.position.set(openW / 2 + 0.09, openH / 2, HD - 0.55); room.add(trimV2);

  // lift door slats covering the top of the opening (light spills below)
  for (let i = 0; i < 5; i++) {
    const s = new THREE.Mesh(new THREE.BoxGeometry(openW - 0.6, 1.18, 0.35), matSlat);
    s.position.set(0, 13 - 1.3 * i - 0.62, HD - 0.7); room.add(s);
  }

  // exterior sky beyond the door
  const sky = new THREE.Mesh(new THREE.PlaneGeometry(220, 90),
    new THREE.MeshBasicMaterial({ map: skyTex, fog: false }));
  sky.position.set(0, 30, HD + 8); room.add(sky);

  // door glow spill + floor light pool
  const doorGlow = new THREE.Mesh(new THREE.PlaneGeometry(openW + 10, 9),
    new THREE.MeshBasicMaterial({ map: shaftTex, color: 0xffc27a, transparent: true, opacity: 0.2,
      blending: THREE.AdditiveBlending, depthWrite: false, fog: false, side: THREE.DoubleSide }));
  doorGlow.rotation.y = Math.PI; doorGlow.position.set(0, 3.2, HD - 4); room.add(doorGlow);
  const pool = new THREE.Mesh(new THREE.PlaneGeometry(34, 22),
    new THREE.MeshBasicMaterial({ map: glowTex, color: 0xffc98a, transparent: true, opacity: 0.1,
      blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
  pool.rotation.x = -Math.PI / 2; pool.position.set(0, 0.05, 49); room.add(pool);

  // ceiling trusses
  function makeTruss(z) {
    const g = new THREE.Group();
    const top = new THREE.Mesh(new THREE.BoxGeometry(W - 2, 0.5, 0.6), matTruss); top.position.y = H - 0.7;
    const bot = new THREE.Mesh(new THREE.BoxGeometry(W - 2, 0.35, 0.4), matTruss); bot.position.y = H - 1.5;
    g.add(top, bot);
    const span = (W - 4) / 5;
    for (let i = 0; i < 6; i++) {
      const x = -HW + 2 + i * span;
      const v = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.8, 0.28), matTruss);
      v.position.set(x, H - 1.1, 0); g.add(v);
      if (i < 5) {
        const dg = new THREE.Mesh(new THREE.BoxGeometry(0.2, 1.5, 0.2), matTruss);
        dg.position.set(x + span / 2, H - 1.1, 0);
        dg.rotation.z = (i % 2 ? 1 : -1) * 0.42;
        g.add(dg);
      }
    }
    g.position.z = z;
    return g;
  }
  [-45, -15, 15, 45].forEach(z => room.add(makeTruss(z)));

  // wall ribs + glowing windows
  for (let z = -52; z <= 52; z += 8) {
    const ribL = new THREE.Mesh(new THREE.BoxGeometry(0.35, H - 1, 1.6), matDark);
    ribL.position.set(-HW + 0.2, (H - 1) / 2 + 0.5, z); room.add(ribL);
    const ribR = ribL.clone(); ribR.position.x = HW - 0.2; room.add(ribR);
  }
  const winMat = new THREE.MeshBasicMaterial({ color: 0x1e6f8f, fog: false });
  [[-HW + 0.12, -22], [-HW + 0.12, 22], [HW - 0.12, -22], [HW - 0.12, 22]].forEach(([x, z]) => {
    const win = new THREE.Mesh(new THREE.BoxGeometry(0.15, 1.1, 22), winMat);
    win.position.set(x, 10.5, z); room.add(win);
  });

  // wall sign
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(16, 4),
    new THREE.MeshBasicMaterial({ map: signTex, transparent: true, fog: false, side: THREE.DoubleSide }));
  sign.position.set(-HW + 0.08, 9, 34); sign.rotation.y = Math.PI / 2; room.add(sign);

  // back-wall service door
  const svcFrame = new THREE.Mesh(new THREE.BoxGeometry(5, 6.4, 0.2),
    new THREE.MeshBasicMaterial({ color: 0x5a3a14 }));
  svcFrame.position.set(10, 3, -HD + 0.1); room.add(svcFrame);
  const svc = new THREE.Mesh(new THREE.BoxGeometry(4.5, 6, 0.3),
    new THREE.MeshStandardMaterial({ color: 0x18202a, roughness: 0.6, metalness: 0.5 }));
  svc.position.set(10, 3, -HD + 0.15); room.add(svc);

  // flickering ceiling light strips
  const ceilStrips = [];
  [-45, -15, 15, 45].forEach((z, i) => {
    const m = new THREE.MeshBasicMaterial({ color: 0xcfe8ff, fog: false });
    const s = new THREE.Mesh(new THREE.BoxGeometry(W - 10, 0.08, 0.7), m);
    s.position.set(0, H - 0.25, z); scene.add(s);
    ceilStrips.push({ mat: m, base: new THREE.Color(0xcfe8ff), i });
  });

  /* ---------------- runway / pad ---------------- */
  const runway = new THREE.Group(); scene.add(runway);
  const runSegs = [];
  const addStripSeg = (x, z, w, l, color) => {
    const m = new THREE.MeshBasicMaterial({ color: 0x000000, fog: false });
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, 0.06, l), m);
    mesh.position.set(x, 0.03, z); runway.add(mesh);
    runSegs.push({ mat: m, base: new THREE.Color(color), d: 56 - z });
  };
  for (let z = 56; z >= -14; z -= 2.6) {
    addStripSeg(-7, z, 0.45, 1.9, 0x2fd4ff);
    addStripSeg(7, z, 0.45, 1.9, 0x2fd4ff);
  }
  for (let z = 56; z >= -14; z -= 4.5) addStripSeg(0, z, 0.3, 2.4, 0xffb347);

  const padC = new THREE.Vector3(0, 0, -20);
  const ringSegs = [];
  for (let i = 0; i < 28; i++) {
    const a = (i / 28) * Math.PI * 2;
    const m = new THREE.MeshBasicMaterial({ color: 0x000000, fog: false });
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(1.15, 0.06, 0.24), m);
